use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " ABI we expect to see within `extern \"{abi}\"`"] # [derive (Clone , Copy , Debug)] # [cfg_attr (feature = "nightly" , derive (Encodable , Decodable))] pub enum ExternAbi { # [doc = " presumed C ABI for the platform"] C { unwind : bool , } , # [doc = " ABI of the \"system\" interface, e.g. the Win32 API, always \"aliasing\""] System { unwind : bool , } , # [doc = " that's us!"] Rust , # [doc = " the mostly-unused `unboxed_closures` ABI, effectively now an impl detail unless someone"] # [doc = " puts in the work to make it viable again... but would we need a special ABI?"] RustCall , # [doc = " For things unlikely to be called, where reducing register pressure in"] # [doc = " `extern \"Rust\"` callers is worth paying extra cost in the callee."] # [doc = " Stronger than just `#[cold]` because `fn` pointers might be incompatible."] RustCold , # [doc = " An always-invalid ABI that's used to test \"this ABI is not supported by this platform\""] # [doc = " in a platform-agnostic way."] RustInvalid , # [doc = " Unstable impl detail that directly uses Rust types to describe the ABI to LLVM."] # [doc = " Even normally-compatible Rust types can become ABI-incompatible with this ABI!"] Unadjusted , # [doc = " An ABI that rustc does not know how to call or define. Functions with this ABI can"] # [doc = " only be created using `#[naked]` functions or `extern \"custom\"` blocks, and can only"] # [doc = " be called from inline assembly."] Custom , # [doc = " UEFI ABI, usually an alias of C, but sometimes an arch-specific alias"] # [doc = " and only valid on platforms that have a UEFI standard"] EfiApi , # [doc = " Arm Architecture Procedure Call Standard, sometimes `ExternAbi::C` is an alias for this"] Aapcs { unwind : bool , } , # [doc = " extremely constrained barely-C ABI for TrustZone"] CmseNonSecureCall , # [doc = " extremely constrained barely-C ABI for TrustZone"] CmseNonSecureEntry , # [doc = " An entry-point function called by the GPU's host"] GpuKernel , # [doc = " An entry-point function called by the GPU's host"] PtxKernel , AvrInterrupt , AvrNonBlockingInterrupt , Msp430Interrupt , RiscvInterruptM , RiscvInterruptS , X86Interrupt , # [doc = " `ExternAbi::C` but spelled funny because x86"] Cdecl { unwind : bool , } , # [doc = " gnu-stdcall on \"unix\" and win-stdcall on \"windows\""] Stdcall { unwind : bool , } , # [doc = " gnu-fastcall on \"unix\" and win-fastcall on \"windows\""] Fastcall { unwind : bool , } , # [doc = " windows C++ ABI"] Thiscall { unwind : bool , } , # [doc = " uses AVX and stuff"] Vectorcall { unwind : bool , } , SysV64 { unwind : bool , } , Win64 { unwind : bool , } , }